quests[94869] = { id = 94869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Hungry Hatchlings", description = "The hatchlings will be hungry! Collect meat from the crabs by the shore and bring it back to the temple to prepare." }
quests[94870] = { id = 94870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggstra Protection Never Hurts", description = "De eggs are nearly ready!\n\n<Brek glances eagerly at both clutches of eggs.>\n\nYa may know somethin' about dis, eh? Jan'alai tells me so. What ya lack in blood, ya make up for in spirit. Help me teach Shaja! Ya spirit alone is not enough for dis ritual. De eggs are imbued with de power of de loa herself and will burst with fiery energy!\n\nWe can protect ya from dis, but first we need feathers. Loa feathers! Collect dem from around de temple... unless ya dare ask de loa herself!", sourceObjective = "Gather 3 Feathers of Jan'alai from the cliffs behind the Temple of Jan'alai.", progress = "Ya got de feathers? Or are ya gonna melt?", completion = "Ah ha! De feathers!\n\nDey will protect ya during de hatchin' ritual, but we must work a little magic on ya first. I taught Shaja the protection blessin' while you were runnin' about.\n\nDo not worry! She is a natural.\n\n<Brek grins wildly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94871] = { id = 94871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eversong", description = "Magistrix Landra Dawnstrider has sent a request for aid in dealing with the local Lightbloom. While typically harmless, it has recently begun to grow at an incredible rate.\n\nMeet up with Arator in Fairbreeze Village to investigate the threat and provide what assistance you can.", completion = "The wildlife is going out of control!", objectives = "Journey to Fairbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94876] = { id = 94876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Some Backbone" }
quests[94878] = { id = 94878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site: Broken Throne" }
quests[94880] = { id = 94880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site: Daggerspine Point" }
quests[94882] = { id = 94882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfect Timing", description = "All is ready! I will now guide ya both through de hatchin' ceremony!\n\nTalk to Shaja and she will use de feathers to protect ya from dem powerful loa energies.", sourceObjective = "Assist Brek and Shaja in hatching the eggs of Jan'alai.", progress = "Hurry! Dem eggs are ready to pop!", completion = "The hatchin' is complete! Hopefully de first of many clutches to come. Jan'alai be praised!\n\nShaja and I will carry on dis legacy and welcome many new hatchlings to our land.", sourceObjectiveStatus = "unverified-source-field" }
quests[94883] = { id = 94883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Dragonhawks to a Flame", description = "I know my uncle can seem... off at times. His talk of de loa always felt like childhood stories to me.\n\nBut ever since Jan'alai returned, I feel her energy too! She flickers, she smolders, she burns red hot. She also brings warmth, light, and life!\n\nBut what I feel from her right now is distress--dat of a mother hen counting her chicks but comin' up short.\n\nLet's check on de hatchlings. We can cover more ground if we split up.", sourceObjective = "Investigate what's going on with the new hatchlings.", progress = "We should keep lookin' around.", completion = "Thank you, {name}. And Jan'alai thanks ya too.\n\nI know dis is my path. By blood and by my own heart. I may never follow my mother into battle, but she will understand I serve de Amani--and Jan'alai--in my own way.", sourceObjectiveStatus = "unverified-source-field" }
quests[94909] = { id = 94909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Pestilence", description = "<This idol proves the depth of your bond with pestilence.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Mot'amra.>", completion = "Many dread Mot'amra. And they aren't wrong to.\n\nBut pestilence, disease, death--these are natural occurrences. Those dat brave their own fear unlock de powerful understandin' of how to cure--or manipulate--these forces.", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94910] = { id = 94910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Growth", description = "<This idol proves the depth of your bond with growth.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Oe.>", sourceObjective = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", completion = "My, my... is dis de idol of growth?\n\nOe is a loa very few know of or worship. They do not form their presence. Instead, they communicate through their domain of de forests, de plants, de world beneath our feet.\n\nTales from our first ancestors make it seem dat Oe followed de Amani from ancient Zandalar. Dat it chose us from all de other tribes when we were still young.", sourceObjectiveStatus = "unverified-source-field" }
quests[94920] = { id = 94920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hal'hadar Battery Core", description = "<The Hal'hadar battery core has been damaged, exposing its inner workings.\n\nAmidst the thin energy wires and familiar metalwork seen in K'areshi technology, you spot gleaming yellow crystals fitted into a golden frame. Small runic letters on the metal are inscribed under it.\n\nPerhaps one of the ethereals in the Howling Ridge in the Voidstorm could help identify this.>", sourceObjective = "Learn more about the Hal'hadar and their technology.", progress = "I may not have fought these ethereals like Baraat has, but I am quite familiar with their technology. I decoded many of their encrypted schematics taken from the field.\n\nTheir use of technomancy and arcanic formula is quite advanced.", completion = "What troubles me is the timing of these attacks. Why now?\n\nAre they allied with the Void... or simply taking advantage of the chaos left in the smoldering wake of Xal'atath's assault?\n\nI cannot say for sure but perhaps there are others who can.", sourceObjectiveStatus = "unverified-source-field" }
quests[94932] = { id = 94932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindings of the Windlord", description = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own.\n\nReturn to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", progress = "Yes, {race}?", completion = "And so you return with the bindings in hand. The Firelord shall be very displeased to have lost these.", objectives = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94933] = { id = 94933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in the Void", description = "Ah, you're there!\n\nOur esteemed Magister Umbric has tasked me with wrangling an able-bodied champion to assist him. An apprentice of his, Leona Darkstrider, is investigating the techniques and methods of the illidari.\n\nIt appears her inquiries may have put her in a bit of trouble.\n\nThe Magister can fill you in. He's in K'aresh now, and he's allowed me to open the way for you if you require transportation.", completion = "I'm glad you've chosen to join me here, {name}.", objectives = "Meet up with Umbric in Shand'orah in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94936] = { id = 94936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bond of Brothers", description = "My brother Tekkan and I were part of a team. Our friend Kariz died fighting de snakes.\n\nKariz's younger brother, Jabat, was consumed by vengeance. He is young and hot-headed, blind to his actions. He took off to kill de snakes. He is in great danger.\n\nThe Right Spear doesn't want to send a rescue, and I won't let their mother cry twice. We are going to get Jabat.\n\nWe need to plan an escape route for when we find Jabat. Tekkan can handle snake burrows with his explosives, but we need a muscle. You in?", sourceObjective = "Destroy Snake Burrows.", completion = "Another snake burrow. We must clear a path forward to find Jabat!", sourceObjectiveStatus = "unverified-source-field" }
quests[94937] = { id = 94937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Quiet on the Northern Front", description = "I only have one small explosive left. Even if Aol'ggin is right about my methods, we can't go back now. I...\n\n<Tekkan chokes on his words, then clears his throat.>\n\nWe can do dis. You lure de snakes out and deal with dem so I can safely blow up de burrow. De escape route will be cleared after dat.", sourceObjective = "Lure the Children of Ula'tek out of their burrows.", completion = "I... I don't know what happened there. I am sorry, {name}.\n\nWith de burrows and de reinforcements gone, dat snake over there... dat is the one who killed... Kariz.", sourceObjectiveStatus = "unverified-source-field" }
quests[94941] = { id = 94941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Recruit Jabat", description = "That large snake was the one who killed Kariz. And now I see Jabat is wounded and in danger. Tekkan is not responsive. I don't know what is wrong with him. There is no time to waste and I don't want to ask what else can go wrong. Dis is bad luck.\n\nCheck on Jabat or take out de large snake right away. Whatever you decide to do first, dat large snake must die.", sourceObjective = "Aol'ggin wants you to slay Hiss'mir.", completion = "Too many friends died down dis ravine. My brother Tekkan and de others...\n\n<Aol'ggin shakes his head.>\n\nDey are sitting with de loa now.\n\nOne day Jabat and I will join dem. But not today.", sourceObjectiveStatus = "unverified-source-field" }
quests[94954] = { id = 94954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkspear Dash", description = "Today, celebrate da Darkspear footrunners. \n\nLong ago, our footrunners ran 'round all da troll empire deliverin' important messages. Dey carried their messages through battle an' storm an' were famous for dey courage. \n\nToday we be celebratin' not dey courage in war, but da courage of some of da messages dey carried--messages of peace an' hope for a better world.\n\nHelp us send a message of hope by joinin' our symbolic run ta Silvermoon. \n\nYa be ready? Well go, mon!", sourceObjective = "Race to Silvermoon City.", completion = "You made it {name}! Ya feel all right, mon?\n\nTime ta celebrate. We all be here together now!", sourceObjectiveStatus = "unverified-source-field" }
quests[94957] = { id = 94957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War of Light and Shadow", description = "The Vanguard has begun to rally its forces to confront the Devouring Host.\n\nReport to Lady Liadrin at the Sunwell to join the offensive.", sourceObjective = "Speak to Liadrin at the Sunwell.", progress = "The Devouring Host tried to break us. Soon, they will face the combined might of the Vanguard.", completion = "We have held the line with blood and Light. Now, we strike back.", sourceObjectiveStatus = "unverified-source-field" }
quests[94967] = { id = 94967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ki'clak Snack Attack" }
quests[94993] = { id = 94993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring in Midnight", description = "The Void encroaches on Azeroth from all sides. Visit the Scouting Map in the Sanctum of Light and choose where you will make your stand.", objectives = "Review the Scouting Map and choose where to begin the Midnight campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94995] = { id = 94995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dye For", objectives = "Welcome, neighbor! I've got just the thing for you here. These dyes I have here will let you give the decor you buy from our local decor vendors an extra pop of color. Take these and try them out, no charge. Be careful, though. Each only works once.\n\nAnd if you want more, alchemists and scribes can grind up herbs to create pigments, when use those pigments at this dye station to create more dyes. You can also probably find them on the Auction House, if you're not interested in making your own.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94996] = { id = 94996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaze of the Dead" }
quests[95008] = { id = 95008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring in Midnight", description = "It's rare that we get to choose our paths in life, but you seem like someone who's seen it all before.\n\n<Soridormi winks.>\n\nDon't dally, this war won't win itself. Go to the Sanctum of Light. Choose where you'll make your first stand.", objectives = "Review the Scouting Map and choose where to begin the Midnight campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95009] = { id = 95009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing the Dash", description = "Have you heard about the race today?\n\nThousands of trolls are gathering to run to Silvermoon City for a celebration!\n\nKalaya could tell you more. They're setting up at the Echo Isles now!", sourceObjective = "Speak with Kalaya on the Echo Isles.", completion = "You're welcome here, {class}.\n\nCome celebrate with us for de race. You not gonna wanna miss it!", sourceObjectiveStatus = "unverified-source-field" }
quests[95021] = { id = 95021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Janoa the Fang (Nightmare)", description = "This creature has established a reputation for particularly vicious ambushes. Envenomed fangs flashing in the dark, followed by frenzied thrashing and then... stillness. \n\nSee if you cannot give it a taste of its own venom.", sourceObjective = "Hunt down Janoa the Fang and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", sourceObjectiveStatus = "unverified-source-field" }
quests[95022] = { id = 95022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Kursak the Coiled (Nightmare)", sourceObjective = "Hunt down Kursak the Coiled and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", sourceObjectiveStatus = "unverified-source-field" }
quests[95023] = { id = 95023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Batani the Scaled (Nightmare)", sourceObjective = "Hunt down Batani the Scaled and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", sourceObjectiveStatus = "unverified-source-field" }
quests[95024] = { id = 95024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Kadani the Claw (Nightmare)", description = "The claw! A miracle of the natural world. An appendage located at the cutting edge of murderous millennia. This creature is all claw and cunning, and you would do best to not fall prey to its violent nature.", sourceObjective = "Hunt down Kadani the Claw and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", sourceObjectiveStatus = "unverified-source-field" }
quests[95069] = { id = 95069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torn Twilight Missive", description = "<The Twilight Missive reads:\n\n\"Our search presses on yet we remain as divided as ever. If we don't unite, then we truly deserved to be abandoned by her!\n\nOf our surviving Speakers, two refuse my missives.\n\nLazaar rallies survivors in the ruins of Deatholme, while Ger'lock amasses a host at the Broken Throne.\n\nThe others have yet to declare for them, which buys us time to continue our search.\n\nWe may yet salvage our broken cause.\"\n\nThe Ranger Captain will want to see this.>", sourceObjective = "Take the Twilight Missive to Silvermoon.", progress = "How fares your fight against the void assaults?", completion = "The Twilight's Blade may be a minor thorn compared to the rampant domanaar or the ethereals attacking Quel'Thalas, but they are still dangerous.\n\nIf we can cut the heads off these snakes, then perhaps what little remains of them can finally dissipate into oblivion.\n\nContinue the fight and keep up the good work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[95070] = { id = 95070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Permafrosted Keystone", description = "<Several void-touched runes flicker across the keystone's surface before dissipating one by one. As the last rune fades, so does the faint hum of power within, leaving nothing but a painfully cold sphere of dark green metal.> \n\nAlthough it doesn't resemble other domanaar artifacts, there was no mistaking the cold, dark magic.\n\nPerhaps Decimus in the Howling Ridge can provide you with more information.>", sourceObjective = "Show the Keystone to someone familiar with Domanaar relics.", completion = "A keystone for a Burning Legion world in the possession of the domanaar is... concerning to say the least.\n\nUntil we know which world this once connected to, there's not much we can do.\n\nPerhaps Allari and her new pupil will be able to reveal more about this void relic. I will send word to her and share what you have found.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[95071] = { id = 95071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Naga Scroll", description = "<The enchanted scroll shimmers with an arcane glint, the text vaguely resembling the elven language.\n\nYou presume it is written in the language of the naga, though the arcane-laced ink appears to move the letters around the scroll.\n\nPerhaps a mage in Silvermoon can help you translate it.>", sourceObjective = "Take the Enchanted Naga Missive to someone in Silvermoon City.", progress = "Yes, {name}?", completion = "You were wise to bring this scroll to me.\n\nI have more questions than answers... who sent this? And who is Nar'jira?\n\nThese new Deeplurk naga will only amplify the Daggerspine threat.\n\nI will ensure the Ranger General is made aware of their presence.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[95114] = { id = 95114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: A Crimson Summons", completion = "Look at you.... following directions already. \n\nExcellent.", objectives = "Meet with Astalor Bloodsworn in Murder Row.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95175] = { id = 95175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anchoring the Defense", description = "We need your help to activate the Singularity Anchor. \n\nWith proper defenses we can counter enemy assaults long enough to activate the device. If the Anchor is destroyed our efforts will be halted.\n\nDo what you can to help us.", progress = "Have you helped us activate the Singularity Anchor?", completion = "We've neutralized numerous anomalies, but the additonal ones remain. We will prepare for additonal activations.", objectives = "Complete the Stormarion Assault event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95215] = { id = 95215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction", description = "<Your hand burns with felfire as a scroll materializes within your grasp. The seal bears the mark of the Illidari.>\n\n{name}, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command.\n\nKayn or Altruis. You can only choose one.\n\nThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.\n\n-Kor'vas Bloodthorn", completion = "I'm glad you selected your second-in-command, {name}.\n\nBut Stormwind mourns today, and we must act.", objectives = "Choose between Kayn and Altruis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95220] = { id = 95220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (30-79) E" }
