quests[95242] = { id = 95242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (81-89) E" }
quests[95245] = { id = 95245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: World Tour", description = "The immediate danger has passed, but there is still much to be done.\n\nGo out and work with our allies to secure what ground we have made against the darkness. Whether it is in Azeroth or beyond, there is still much to be done.", completion = "Back so soon? Impressive!", objectives = "Complete faction features in Midnight zones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95253] = { id = 95253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shocking Appetites" }
quests[95259] = { id = 95259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (81-89) E" }
quests[95268] = { id = 95268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Tools, New Heights", description = "There is another sort of Void power I know you will be interested in. An Ascendant Voidcore is difficult to come by, and even more difficult to work. With the Voidforge completed, I can now weave a magnificent Nilhammer capable of such things. Of course, I will need you to help with the materials. It will take time.\n\nTake this chunk of Hungering Oblivium. It can devour moments of extreme violence to be catalyzed to new heights of power, but I don't think you'll have any trouble managing that, will you?", sourceObjective = "Catalyze the Hungering Oblivium with violence by defeating Midnight Season 1 raid bosses or completing Mythic+ dungeons and Bountiful Delves to begin forging the Nilhammer.\n\nThe Nilhammer will allow you to use Ascendant Voidcores to increase the item level of worthy weapons and trinkets.", progress = "Have you fed your pet rock yet, {name}? I would not suggest leaving Oblivium on your person for extended periods of time...", completion = "I can feel the Hungering Oblivium radiating power! Well done, {name}. We have taken the first step towards even greater power. It will take me some time to prepare more Oblivium to continue our work here.", sourceObjectiveStatus = "unverified-source-field" }
quests[95269] = { id = 95269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Nilhammer", description = "Our nascent Nilhammer coalesces! But I will need to weave the Void energies from more Hungering Oblivium into it before it can fully take form. Luckily I have prepared another piece for you to catalyze. Extreme violence, remember?", sourceObjective = "Catalyze the Hungering Oblivium with violence by defeating Midnight Season 1 raid bosses or completing Mythic+ dungeons and Bountiful Delves to continue forging the Nilhammer.\n\nThe Nilhammer will allow you to use Ascendant Voidcores to increase the item level of worthy weapons and trinkets.", completion = "Ah, well done. Another successful Oblivium catalyzation. The Nilhammer grows stronger!", sourceObjectiveStatus = "unverified-source-field" }
quests[95271] = { id = 95271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ascendant Nilhammer", sourceObjective = "The Ascendant Nilhammer! A tool truly worthy of an artisan of my skill. The things I will be able to create... Of course, you will be rewarded for your efforts. Take this Ascendant Voidshard. You will need several more before you can coalesce them into an Ascendant Voidcore. I will help you transfer its energies into your most powerful equipment at the Voidforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[95276] = { id = 95276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Push", description = "Our forces are starting to move out to take the fight to Xal'atath. \n\nI've received word there are many areas that you've visited that could still use some aid. \n\nWe must focus our attention on the counter offensive. Can you help those that are in need?", progress = "There's plenty out there that can be done.", completion = "Fine work {name}. \n\nThere's plenty to do now that you've taken care of those issues.", objectives = "Reach level 90.\n\nQuests in Silvermoon City, Eversong Woods, Zul'aman, Harandar, and Voidstorm will now scale to your level.\n\nWorld Quests are now unlocked.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95279] = { id = 95279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebulous Voidcores: Gold", progress = "Back for more Nebulous Voidcores? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all?\n\nEven in the Voidstorm we can find uses for the gold. It has the most interesting properties when subjected to a touch of Void energy under the right conditions!", completion = "I knew you couldn't say no. I trust you'll put these Nebulous Voidcores to good use, {name}." }
quests[95290] = { id = 95290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebulous Voidcores: Voidlight Marl", progress = "Back for more Nebulous Voidcores? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all?\n\nVoidlight Marl is a fascinating substance! I am always happy to have more to experiment with. It is usually difficult to come by such Light-touched reagents in the Voidstorm.", completion = "I knew you couldn't say no. I trust you'll put these Nebulous Voidcores to good use, {name}." }
quests[95304] = { id = 95304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebulous Voidcores: Veteran Dawncrest", progress = "Back for more Nebulous Voidcores? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all?\n\nThose crests you use to empower equipment could be put to great use in my workshop. I can always use new materials to experiment with.", completion = "I knew you couldn't say no. I trust you'll put these Nebulous Voidcores to good use, {name}." }
quests[95324] = { id = 95324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Beyond the Roots", description = "Your actions in Harandar caused quite an uproar. The elders are up in arms. The rootwardens are worried. It's really quite exhausting.\n\nBut there is good news as well. Orweyna has heard rumblings from every corner of the roots. She tells me of haranir who wish to see the world as she does--who feel compelled to seek the goddess beyond the boughs of Harandar.\n\nI will handle things in Harandar. Go to your leaders. Tell them that the haranir are ready to join the fight.", completion = "The haranir seek to join the fight against the Void?\n\nFar be it from me to look a gift hawkstrider in the mouth. Halduron has vouched for both their strength and their tenacity. We shall need a great deal of both, in the battles to come.", objectives = "Bring word to Lor'themar in the Sanctum of Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95336] = { id = 95336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzied Fossicking", description = "Ya be down for helping me out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty grateful ta ya. Just bring them back ta me. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", sourceObjective = "Collect 30 Rocks in your neighborhood.", progress = "Did ya help out Shajanji?", completion = "Oh yah, I can use these--I mean Shajanji will be happy with these in her collection.\n\nYa did good.", sourceObjectiveStatus = "unverified-source-field" }
quests[95355] = { id = 95355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Messenger", description = "<This Lurker was carrying some items it looted from a fallen soldier.\n\n...These items feel familiar.\n\nThe letter is addressed to Namaji in Amani'Zar Village. Perhaps these items should be returned to her.>", sourceObjective = "Bring the Hastily Written Note to Namaji at Amani'Zar Village.", progress = "What's this?", completion = "Dis belongs to... Where did ya find dis?\n\n<You explain how you came across these items.\n\nPanicked, Namaji quickly reads the letter. Her brow furrows.>\n\nDat idiot...", sourceObjectiveStatus = "unverified-source-field" }
quests[95373] = { id = 95373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nebulous Endeavour", description = "I see you haven't come across a Nebulous Voidcore before. I can now weave them for you from the energies of the Catalyst as they accumulate, but you'll have to provide raw reagents.\n\nWith the Voidcore in hand, you'll have to seek out powerful enemies in order to transmute it into useful equipment. Its capable of capturing part of their essence to become something more powerful that you can put to use in the battles ahead.", sourceObjective = "Acquire a Nebulous Voidcore from Orin, then defeat a Midnight Season 2 raid boss, complete a Mythic+ dungeon, open a Delve's Bountiful Coffer, or complete a Nightmare Prey Hunt for the opportunity to spend the Voidcore to gain new equipment.", progress = "Back already, {name}? Were you able to transmute the Nebulous Voidcore?", completion = "Ah, looks like you found something shiny after all! The Voidforge will provide me with additional reagents to weave more Nebulous Voidcores over time, so be sure to check back later.", sourceObjectiveStatus = "unverified-source-field" }
quests[95381] = { id = 95381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire in the Sky" }
quests[95387] = { id = 95387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Neighbor's Junk is Another Troll's Treasure", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Ya be having any goods from ya neighborhood for trade?", completion = "Oh yeah, I be finding a real good use for these.\n\nHere ya go, a fair trade, ya?" }
quests[95391] = { id = 95391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site Renowned", description = "Adventurer you have shown a flair for dealing with these Ritual Sites. \n\nIt is only appropriate that we should reward you for your continued assistance.", sourceObjective = "Speak with Lady Darkglen in Silvermoon City.", completion = "My have you been busy. I again applaud your efforts. I fear some day you may not need any assistance in dealing with these Rituals. \n\nAlas, that is not today, but take this reward it will help you continue to hone your skills and tactics out there.", sourceObjectiveStatus = "unverified-source-field" }
