quests[95406] = { id = 95406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Animals", description = "Oh thank goodness you are here!\n\nSome of my precious orange kitties were so eager to play in the neighborhood they've all run off to explore. Please help me find them!", objectives = "Find 10 Lost Cats", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
