quests[95413] = { id = 95413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Community Engagement", description = "Ah hello, {name}. I have a flier for you.\n\n<Vaeli hands you a glossy piece of paper.>\n\nDON'T MISS OUT!!!\n\nDon't miss this amazing deal available only to you! Present this coupon on your next purchase from your neighborhood endeavor trader, and get bonus items for free!\n\nCoupon valid for one week. Terms and conditions apply.", sourceObjective = "Purchase an item from an endeavor trader found in your neighborhood.", completion = "<With your recent decor purchase, you are gifted a bundle of goods.>", sourceObjectiveStatus = "unverified-source-field" }
quests[95416] = { id = 95416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Postal", description = "With so many new residents, mail in the neighborhoods is really starting to pile up. So many routes and just one of me! If only I could deputize an assistant mail carrier...\n\nSay, {name}, would you be willing to help out? I've got some juicy parcels from the dead letter office I could offer in thanks.", sourceObjective = "Complete a neighborhood postal route.", progress = "Neither scourge nor fel nor void nor dragon's flame shall stay we couriers from the swift delivery of our entrusted missives!", completion = "You're a lifesaver! And we're certain none of those letters or packages ended up in a ditch somewhere, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[95429] = { id = 95429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift of Foot" }
quests[95435] = { id = 95435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shade and Claw" }
quests[95438] = { id = 95438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Animals", description = "{name}, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me she lost track of some of her tiny pets throughout the neighborhood! She's asking for assistance from anyone who can help!\n\nHelp find her lost animals right away!", sourceObjective = "Find 10 Lost Animals in the neighborhood and bring them to Kara Meldansen.", progress = "Oh please do hurry!\n\nI'm sure they are off having the most grand adventures but I worry so!", completion = "Thank you so much! I am so glad to have all my babies back!", sourceObjectiveStatus = "unverified-source-field" }
quests[95439] = { id = 95439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Animals", description = "{name}, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me of an issue she is having within the neighborhood, specifically having to do with her large collection of pets!\n\nShe seemed very stressed and worried, I would not delay on seeking her out to help!", sourceObjective = "Find Kara in your neighborhood.", sourceObjectiveStatus = "unverified-source-field" }
quests[95440] = { id = 95440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Housewarming", description = "Kirin Tor scholars have argued for centuries over the semantics of a \"gathering\".\n\nHow many people are required? For how long must they remain? Who is bringing the beverages?\n\nDebates have raged into the night. Papers written. Research grants awarded.\n\nConsensus yet eludes the scholars, but they still meet often to deliberate. They take turns bringing beverages.", sourceObjective = "Gather with at least four other players inside a player home while the homeowner is present.", sourceObjectiveStatus = "unverified-source-field" }
quests[95448] = { id = 95448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dose Makes the Poison" }
quests[95449] = { id = 95449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snakes in the Grass" }
quests[95451] = { id = 95451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Ordered the Bag of Snakes?" }
quests[95453] = { id = 95453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollan Repatriation" }
quests[95468] = { id = 95468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope in the Darkest Corners", description = "I can't imagine what will happen to Quel'Thalas if the Sunwell falls to the forces of the Void.\n\nWe need you out on the battlefield, {name}. Bring hope and heroism to the people across these lands.", completion = "Well done, {name}!", objectives = "Complete various activities in Midnight zones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95482] = { id = 95482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Animals", description = "{name}, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me of an issue she is having within the neighborhood, specifically having to do with her large collection of pets!\n\nShe seemed very stressed and worried, I would not delay on seeking her out to help!", sourceObjective = "Find Kara in your neighborhood.", sourceObjectiveStatus = "unverified-source-field" }
quests[95484] = { id = 95484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truffle Scuffle" }
quests[95520] = { id = 95520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purging the Vaults", description = "De fiends of dis temple would see us all dead. We are all dat stands between them and de mainland, you understand? We hold dem here.\n\nNot one scale, not one bony finger, none of them will leave dis temple while we breathe.\n\nGet out there and cut them down.", sourceObjective = "Complete Temple Patrols, Strikes, Incursions, and defeat Ancient Foes in the Vaults of Atal'Utek.", progress = "Send their souls howling back to Ula'tek.", completion = "De fiends here are some of de nastiest, foulest creatures on Azeroth. And I think they're startin' to fear you.\n\n<Abdumati smiles.>\n\nIf we survive dis, they're gonna write songs about you.", sourceObjectiveStatus = "unverified-source-field" }
quests[95521] = { id = 95521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Med'jai Medallion", description = "<The ancient gem pulses faintly. Scratches adorn its sides as if pried away with desperate eagerness. Perhaps the troll spirit, Me'si, will know where this came from.>", sourceObjective = "Show the gem to Me'si at the temple hub.", completion = "I have not seen de likes of dis since I walked de land of de livin'.\n\nI believe ye found one of de honored Med'jai medallions, possessed by heroic warriors believed to guard dis temple wit' their very souls.", sourceObjectiveStatus = "unverified-source-field" }
quests[95522] = { id = 95522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Death, Guardians in Stone", description = "In de legends passed down, dey speak of a group of heroic guardians whose sacrifice protect us to dis day. These honored few, known as de Med'jai, adorned their belts with gems like these--de better to draw their enemies in and defeat dem.\n\nWe were told dey went on a great expedition to fight de evil abroad, but it seems de greatest of de evils was within--below our feet.\n\nPlease, {name}, search for dis gem's true home. If our ancestor spirits watch over us, perhaps we will find their resting place.", sourceObjective = "Search for the long-dead owner of this gem.", completion = "I see much has changed, gokinye.\n\nAs a warrior, I fought for de Amani on de field of battle. My blade was feared amongst our enemies.\n\nWhen my people asked for me to watch over dis temple, I was de first to step forward. There is no greater honor than to give your life for your people. And I am proud to do it.\n\nBut looking around, I wonder. Was our sacrifice in vain?", sourceObjectiveStatus = "unverified-source-field" }
quests[95523] = { id = 95523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worthy of the Past", description = "De Soulcoilers must pay, {name}.\n\nDe Soulcoilers believed their actions saved de Amani. Instead, our people and our future was plundered. We did not realize until it was too late.\n\nEnd them. Shatter their very souls so that even de great Mueh'zala cannot put dem back together.", sourceObjective = "Annihilate the essences of the Soulcoilers.", progress = "Defeat is not enough, {name}. Annihilate their very souls.", completion = "Dis is good. Their cursed souls will only know oblivion.", sourceObjectiveStatus = "unverified-source-field" }
quests[95524] = { id = 95524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unremembered", description = "I am not de only Med'jai tasked with keeping sentinel over de priests. There were three of us, entombed in stone that matched how we looked in life.\n\nI must know if dey are still there. Can you help me find them? My body is bound in dis stone, but my spirit is not. Bring my gem to those places, if you can find dem.\n\nIf we cannot wake dem, we will at least honor dem.", sourceObjective = "Find the resting place of Thaze'ala's fellow guardians.", progress = "Have you found dem, {name}? My brothers and sisters.", completion = "Thank you, {name}. I had wished for better, but it helps to know their fates in dis world.", sourceObjectiveStatus = "unverified-source-field" }
quests[95525] = { id = 95525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Vigil", description = "De temple has changed since I began my watch, {name}. When you first woke me, all I saw was corruption and impure spirits. De consequence of our weakness.\n\nNow, I see dat we have not failed. De battlefield has changed, as dey always do.\n\nPlease take my gem and bring it back to de others like you. Perhaps my spirit can become a force for good on dis new battlefield, in a new way.", sourceObjective = "Return to Me'si with Thaze'ala's awakened spirit gem.", completion = "Ah, I can hear Thaze'ala now. You have awoken her heroic spirit in dis gem, {name}.\n\nPerhaps with her wisdom we will learn much about how our great shame was only held back by de heroic sacrifice of our people.", sourceObjectiveStatus = "unverified-source-field" }
quests[95529] = { id = 95529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spearin' Sky Snakes" }
quests[95547] = { id = 95547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site Challenge Report: Tendrils", description = "<The information in the scrolls speaks of a mysterious vine attracted to the high levels of magic at Ritual Sites. This is the type of information Lady Darkglen needs to be told to better prepare for countering future Ritual Sites.>", sourceObjective = "Return your report to Lady Darkglen in Silvermoon City.", progress = "What do you have there?", completion = "Ah, I have seen this before, but it is good to know that these tendrils are present in this region. It is common at Ritual Sites, and if you stay aware of your surroundings you can easily sidestep them.\n\nIf you find any information on other challenges we might face in Ritual Sites, be sure to bring them to me! Many challenges will be tougher to identify. We have our work cut out for us, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[95548] = { id = 95548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Sample", description = "<This sample is tainted and reeks of unknown scents.\n\nPerhaps Lady Darkglen would be interested in studying it further.>", sourceObjective = "Return the tainted sample to Lady Darkglen.", completion = "How delightfully revolting.", sourceObjectiveStatus = "unverified-source-field" }
quests[95549] = { id = 95549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Magical Alarms", description = "I have a request.\n\nThese Ritual Sites invoke some interesting magic. I would like you to obtain some sample readings.\n\nYou don't need to concern yourself with the details. Just visit the area I will mark on your map and press the button.\n\nYou may end up garnering some extra attention when you do so.", sourceObjective = "Use Lady Darkglen's device in a Ritual Site.", progress = "That is the look of success.", completion = "Such delightful data. Now the real work begins.", sourceObjectiveStatus = "unverified-source-field" }
quests[95550] = { id = 95550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thin Their Ranks", description = "I don't like it.\n\nWe have far too many scouts returning wounded from these so-called ritual sites.\n\nThin out the ranks of these cultists.", sourceObjective = "Defeat enemies in a Ritual Site.", progress = "Is the job done?", completion = "Good.\n\nFor far too long we have been beset by threats. Striking back will send a message.", sourceObjectiveStatus = "unverified-source-field" }
quests[95551] = { id = 95551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misappropriated Treasures", description = "<It seems the cultists have added theft to their repertoire.\n\nYou should reclaim the stolen treasures from the Ritual Site and return them to Rae'ana.>", sourceObjective = "Return the stolen treasures to Rae'ana.", progress = "Oh? What do you have there?", completion = "Such wonderful artifacts. I shall make sure these are cataloged immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[95552] = { id = 95552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Obelisk Investigation", description = "{race}, we have reports that the leaders of the Ritual Sites are using dark obelisks to bolster their forces with malevolent boons.\n\nI need you to investigate the objects they are using to gain these boons.", sourceObjective = "Investigate the sources of the malevolent boons in a Ritual Site.", progress = "What do you have to report?", completion = "Now that we are aware of how they are getting the boons, I will identify these dark obelisks' weaknesses. I should soon have the information you need to destroy them when they are active.\n\nGood work, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[95553] = { id = 95553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manifested Density", description = "I'm hearing strange murmurings from my scouts.\n\nSome are claiming that strange manifestations are appearing and cursing intruders.\n\nCould I ask you to investigate and see if there is any truth to these rumors?", sourceObjective = "Complete a Ritual Site.", completion = "Astounding.\n\nI don't know what these cultists will do next, but at least now we can be better prepared for their current monstrosities.", sourceObjectiveStatus = "unverified-source-field" }
quests[95554] = { id = 95554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questionable Power", description = "<This creature was being enhanced by an unknown magic.\n\nPerhaps you should gather more of these fragments.>", sourceObjective = "Collect Fragments of Power.", progress = "You have something for me?", completion = "Curious.\n\nI wonder what they hope to achieve with such enchantments?\n\nI guess time will tell.", sourceObjectiveStatus = "unverified-source-field" }
quests[95564] = { id = 95564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Serpent's Tail", description = "De Shadowpine shamans are at our hash'ey's command. We speak de language of fire from de wing of Jan'alai, but we also need help.\n\nWith de help of the other tribes, we have secured this camp. But we won't hold it for long without your help.\n\nI have a few things I would ask you to do, hash'ura, if you are willin'.", sourceObjective = "Assist Amani forces across the Serpent's Tail.", progress = "Without dis base, we will never have de foothold to stop de monsters from attacking de rest of Zul'Aman.", completion = "Mado-ru, hash'ura, for helpin' secure our camp.\n\nNow I can help de hash'ey in her time of greatest need.", sourceObjectiveStatus = "unverified-source-field" }
quests[95572] = { id = 95572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Pains" }
quests[95573] = { id = 95573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Broken Bonds" }
quests[95575] = { id = 95575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forest Mana Spores" }
quests[95576] = { id = 95576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Majestic Eagle Statue", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Hello, {name}. How can this one help you?", completion = "Ah, this is just what I have been looking for.\n\nIt's not much, but please take this in return." }
quests[95580] = { id = 95580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Slay the Restless" }
quests[95583] = { id = 95583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressed Sanguithorn", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Hey {name}, what's up?", completion = "Oh my, what a well preserved specimen.\n\nPlease, let me give you this in exchange." }
quests[95584] = { id = 95584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Aromatic\" Bottle", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Interested in a deal, {name}?", completion = "Hah, I can see why you want to get rid of this.\n\nDo not worry, my friend. I know just the person who would be interested in this.\n\nIt's not worth much though, yes?" }
quests[95585] = { id = 95585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone Pen", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Hello, {name}. How's your day going?", completion = "You can never have enough pens I always say.\n\nPlease, take this in recompense." }
quests[95587] = { id = 95587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deactivated Amani Hex Ward", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Yes, {name}?", completion = "It's always fascinating to see how different cultures ward their homes, had this any magical powers to it.\n\nI offer this in trade." }
quests[95589] = { id = 95589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Waraxe", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Need some choppin' done?", completion = "I go through axes quick as anyting. \n\nI'll happily take it off yer hands." }
quests[95590] = { id = 95590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Construction Hammer", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "How's it going, {name}?", completion = "I can never turn down a good hammer. Or a good apple tart. Heck, I'll even eat a bad apple tart.\n\nI don't suppose you have an apple tart? No? Well I appreciate the hammer none the less!" }
quests[95592] = { id = 95592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ossein Fish Trinket", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Lookin' to buy some fish?", completion = "An old bone trinket? Heck, I'll take anything that'll improve our fishing!\n\nPlease take this, from all of us." }
quests[95593] = { id = 95593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torga Statue", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Always nice to see land dwellers. What can I get you?", completion = "Ah Torga, you've been put through so much, and yet still you look out for us.\n\nThank you, {name}. Please, it's not much, but take this." }
quests[95595] = { id = 95595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrimshaw Ward", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Anyone follow you in?", completion = "Yeah, I can use this.\n\nTake this. I owe no debts to no-one." }
quests[95597] = { id = 95597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jan'alai Bibelot", description = "Ya be down for helping ol' Griftah out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", progress = "Hey {name}! How are you doing?", completion = "I'll take anything that can help the farm out.\n\nPlease, let me give you this." }
quests[95598] = { id = 95598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Slay Children of Ula'tek" }
