quests[95662] = { id = 95662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suspicious Stew" }
quests[95673] = { id = 95673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Scare-gull", description = "Hey there, could ya help a poor troll down on their luck?\n\nI'm looking for some feathers from ya neighborhood.\n\nIf ya give the birds around here a good scare, they'll take off and drop some, just bring them back here.", sourceObjective = "Collect 25 Bird Feathers in your neighborhood.", progress = "Did ya get them feathers?", completion = "Ya be the best, {name}.\n\nI was running outta stock... ings. I be making... socks with... feathers?\n\nYup, feather socks. Nothing else.", sourceObjectiveStatus = "unverified-source-field" }
quests[95695] = { id = 95695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrier D" }
quests[95768] = { id = 95768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Stuff's Better Than Your Stuff", description = "Hey there, {name}.\n\nI set up shop to trade some of our neighborhood goods with our new friends here, and I've been selling like hotcakes!\n\nI could use a break though, would you mind watching the shop for me? If any customers come by, just offer them what you think is best.", sourceObjective = "Sell the perfect item for 6 Amani Visitors in your neighborhood.", progress = "Are you ready to step in?", completion = "Thank you so much! I can take it over again. You did really well!", sourceObjectiveStatus = "unverified-source-field" }
quests[95779] = { id = 95779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moments in a Mug", description = "A man who knows his way around a drink deserves the finest brew. I have just the thing in mind for my friend, Flynn.\n\nThe ingredients I need are within my family's brewery in the Valley of Four Winds. I would fetch them myself, but a brewmaster must also know when to sit, breathe, and appreciate what is within the mug.\n\nWould you go to Stormstout Brewery and bring those ingredients to me, friend?", sourceObjective = "Journey to the Valley of Four Winds and enter the Stormstout Brewery. Inside, retrieve 6 ingredients. Optionally, acquire the Stormstout Brewery Lantern as well.", progress = "Did you manage to get the ingredients?", completion = "Those look like very good quality ingredients. You must know a thing or two about brewing!\n\nThank you, friend. I will make enough for you as well, if you'd like to try it!", sourceObjectiveStatus = "unverified-source-field" }
quests[95780] = { id = 95780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope for the Orphans", description = "Garona and I both don't talk about our childhoods much. There's not a lot worth saying.\n\nThe children in that orphanage in Shattrath--they're living what we lived. I'm not asking you to fix that. I'm asking you to show up and remind them the world holds something worth fighting for.\n\nFor me, revenge was worth fighting for. But maybe they can have a brighter future.\n\nGo play games with them. Try to show them what a person worth looking up to actually is.", sourceObjective = "Journey to the Shattrath orphanage and play games with the kids. Optionally, acquire the Wooden Toy Sword as well.", progress = "Kids say the damndest things, don't they...", completion = "You actually went. I wasn't sure you would.\n\nThe kids will remember that. They always remember the ones who show up.\n\nWhat's that wooden sword you got there? Let me take a look.\n\n<Vanessa and Garona flip over the sword, and notice it has a message engraved.>\n\n\"For a hero.\"\n\nThere is probably a great spot to hang this in the Arcantina.", sourceObjectiveStatus = "unverified-source-field" }
quests[95781] = { id = 95781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Wax Like Home", description = "Skitter like Myritt. Myritt is sad, wants gift for his friend. \n\nCandle is best gift. Help find the best candle for Myritt.", sourceObjective = "Journey to place to collect candles. Optionally, acquire the Kobold Candle Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[95794] = { id = 95794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-cryption Process" }
quests[95804] = { id = 95804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Children of Ula'tek", description = "Are these tortollans lost? How long have dey been here?\n\nWe have a settlement of dem near de Shrine of Filo, but dis is a place dey should not be.\n\nA day not long ago, I would have chased dem off. But we've been havin' good luck with outsiders.\n\n<A hint of a smile crosses Zul'jarra's face. It's the first you've seen since before Malacrass's return.>\n\nWe should talk to dem. Maybe dey know how dis started.", sourceObjective = "Ask Captain Tokka what he has seen at Tokka's Landing.", progress = "We need to find out more about dis island if we gonna find our people.", completion = "Zul'jan...\n\nWhy would you do dis, brother?", sourceObjectiveStatus = "unverified-source-field" }
quests[95807] = { id = 95807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Over Easy" }
quests[95815] = { id = 95815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downhill Jam" }
quests[95842] = { id = 95842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Void Assaults", description = "Both Void forces and old enemies press us in this turbulent time. We must stay vigilant and let no faction gain a foothold.\n\nYou must put a stop to these Void assaults! Stay alert, our scouts report some factions may be using the smaller strikes to prepare for a major incursion. \n\nIf so, I know you will help with the defense.", sourceObjective = "Complete Void Strikes and Void Incursions in Midnight.", completion = "Thank you {class}, our enemies once again are thwarted. With defenders like yourself we shall not fail.", sourceObjectiveStatus = "unverified-source-field" }
quests[95843] = { id = 95843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Ritual Sites", description = "There have been many enemies that seek to use dark rituals to send horrors our way. The rangers have always risen to challenge and dealt with them. \n\nWith the pressure on our forces, I must ask you to take up this mission. There are dangerous Ritual Sites that must be disrupted. \n\nOur enemies will most likely try again, so you must be dogged and continue to thwart them each time they make the attempt.", sourceObjective = "Complete Ritual Sites in Midnight.", completion = "These Ritual Sites are one more threat we now must face. Your diligence in protecting our lands is not going unnoticed, and we are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[95856] = { id = 95856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 61" }
