quests[95931] = { id = 95931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open Sea Fishing" }
quests[95933] = { id = 95933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traces in the Dark", description = "Champion, Riftblade Maella would like to speak with you again.\n\nThe dark particles you have brought us, the information you've been gathering on our enemies and the countless victories you have bought for Quel'Thalas have not gone unnoticed.\n\nIt seems Maella has a plan. Seek her out when you can.", sourceObjective = "Speak to Riftblade Maella in Silvermoon City.", progress = "Your efforts against these void and ethereal threats has, yet again, been invaluable. But our work is not yet over.", completion = "For now, continue your efforts in protecting Eversong and Zul'Aman.\n\nThese threats, be it void, ethereal or other, are unlikely to simply give up and slink away.\n\nRout them at every turn you can while I gather allies and prepare for our next move.\n\nI will be in touch in due time.", sourceObjectiveStatus = "unverified-source-field" }
quests[95942] = { id = 95942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Venom Ambush" }
quests[95952] = { id = 95952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Breath and Bile" }
quests[95953] = { id = 95953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Congealed Venom" }
quests[95954] = { id = 95954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Foe", description = "You have done well, {name}, but a shadow remains cast over the temple, in the form of the High Priest Jin'tal.\n\nA particularly fervent and ambitious priest in life, I am unsurprised that he has survived into undeath. I sense that he practices his abhorrent faith in the nearby Mortuary.\n\nPlease, {name}. End him. I will help you if I can.", sourceObjective = "Enter the Vault of Restless Bones and defeat High Priest Jin'tal.", completion = "The High Priest's presence has dissipated, at least for now. It remains to be seen if he's capable of taking form again. \n\nBut if so, we will be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[95962] = { id = 95962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Vengeance for the Dead" }
quests[95972] = { id = 95972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Patrol: Ash to Ash" }
quests[95973] = { id = 95973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of the Darkwell", description = "Magister Umbric has been keeping an eye on the Twilight's Blade, receiving reports from the field. \n\nHe thinks something is afoot. \n\nThat is not all. He said that he has also been keeping an eye on Arator since the Darkwell, and has developed... concerns about him.\n\nGo, speak with him.", sourceObjective = "Meet Magister Umbric by the Shining Span.", completion = "It is good to see you. We have hardly any time to catch our breath.\n\nBut our enemies do not rest, either. The Twilight's Blade have been active, again.", sourceObjectiveStatus = "unverified-source-field" }
quests[95974] = { id = 95974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Abandoned Camp" }
