quests[96004] = { id = 96004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: A Slithering Threat", sourceObjective = "Hunt down Janoa the Fang, Kursak the Coiled, Kadani the Claw, or Batani the Scaled in Nightmare Mode in Midnight Zones.", completion = "Snake creatures? Delightful.", sourceObjectiveStatus = "unverified-source-field" }
