quests[96029] = { id = 96029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Face the Swarm" }
quests[96048] = { id = 96048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Time to Strike", description = "<A void-touched missive materializes before you.>\n\n{name},\n\nYour efforts against the recent void and ethereal incursions have paid off. It's time we take the fight to them.\n\nMeet me at the Ranger-Captain's strike station in Silvermoon.\n\nDo not delay.\n\nRiftblade Maella", sourceObjective = "Meet Riftblade Maella overlooking the Bazaar in Silvermoon.", completion = "Shortly after Xal'atath disappeared, rogue void forces and ethereals attacked our lands.\n\nWe discovered they're operating from former Legion-controlled worlds, giving my Riftwardens a trail to follow.\n\nWith Quel'Thalas still under threat from these attacks, large scale support from Silvermoon is out of the question.\n\nLuckily, I've found like-minded allies to join our assault.", sourceObjectiveStatus = "unverified-source-field" }
quests[96049] = { id = 96049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalkers of the Stars", description = "With the help of Belath Dawnblade and Decimus, we've learned our enemies orchestrate their attacks from former Legion worlds.\n\nI've requested the demon hunter's aid in navigating these worlds and fortifying our defenses.\n\nSeek them out and lend them any assistance they need. Inform Belath we mobilize soon.", sourceObjective = "Recruit Belath and his Illidari in Murder Row for Maella's expedition.", progress = "I've come to learn much about demon hunters recently. \n\nAllari the Soul Eater has overseen the training of Leona Darkstrider and other ren'dorei following her path.\n\nI've seen how they fight... how they hunt. This and their expertise with Legion worlds will be critical in this mission.", completion = "So, Leona is joining us?\n\nGood. I had hoped to see her in the field.\n\nAllari and Belath's knowledge of Legion worlds will help us navigate the terrain when we arrive... wherever it is our enemies are holed up.\n\nLet's just hope our enemies are inhabiting a world the demon hunters have information on.", sourceObjectiveStatus = "unverified-source-field" }
quests[96051] = { id = 96051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Cold Rift", description = "The Legion keystone and the dark particles you found gave us a needle in the endless, vast haystack of the Twisting Nether.\n\nWith the Cynosure of Twilight, the artifact used to open the way to the Voidstorm, we can thread this needle and open a rift to our enemy's doorstep.\n\nWith the components in place, my riftwardens stand at the ready.\n\nTake up the Cynosure and point and be ready, {name}.", sourceObjective = "Take up the Cynosure of Twilight and open the Rift.", completion = "<Maella shields herself from the cold gust of howling wind.>\n\nOur location is convenient but the weather is not.\n\nAt least this area is clear. We can break ground here.\n\nWhile Y'mera works to bring in the remainder of our forces and supplies, let's gather our bearings.", sourceObjectiveStatus = "unverified-source-field" }
quests[96052] = { id = 96052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Mana Rift", description = "The energy from the Hal'hadar battery core and dark particles allowed us to piece together a faint trail of nether energy.\n\nWith the Cynosure of Twilight, we can illuminate and ignite this trail, taking us directly to our enemy's doorstep.\n\nThe anchors are in place and my riftwalkers await your move.\n\nTake up the Cynosure and point. Let us see what awaits us on the other side.", sourceObjective = "Take up the Cynosure of Twilight and open the Rift.", completion = "<Maella squints, her eyes narrowing at the heavy fog and plumes of arcane energy in the distance.>\n\nThis is definitely the right place. I can smell the stench of burning mana from here.\n\nOur landing spot has given us a place to carve out a holdout for our forces.\n\nWhile Y'mera transports the rest of our forces, let's gather our bearings and see what awaits us on this world.", sourceObjectiveStatus = "unverified-source-field" }
quests[96053] = { id = 96053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Frozen Wastes", description = "We still hold the element of surprise, which gives us a moment to fortify our position.\n\nWhile Y'mera opens a more stable travel network for the rest of our forces, our scouts have gone ahead to survey the terrain.\n\nMeet with them in the field and activate our surveillance beacons.\n\nI will remain here to cover the arrival of our reinforcements.", sourceObjective = "Meet with the Scouts in the field and activate the Surveillance Beacons.", progress = "Imperator Pertinax's fortress spans deep under the ice. \n\nIt would seem his forces are not recent arrivals on this hellscape.", completion = "These beacons will allow us to observe our enemies closely and keep tabs on threats around the region.\n\nAfter all, not everyone on our strike team is blessed with spectral sight like mine.\n\nNow that we've got eyes on the enemy, we have a new opportunity to sow chaos across this wretched wasteland.", sourceObjectiveStatus = "unverified-source-field" }
quests[96054] = { id = 96054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Mana-Bog", description = "Our sudden arrival allows us a brief moment to fortify our hold here.\n\nWhile Y'mera works on bringing the rest of our forces through a more stable network, our scouts have gone ahead to survey the terrain and the enemy.\n\nMeet with them in the field and activate our surveillance beacons.\n\nI will remain here with Y'mera and Decimus should any of those skiffs overhead decide to pay us a visit.", sourceObjective = "Gather Scouting Reports from Baraat, Belath, and Tala'saan.", progress = "Our enemy has fortified their position here, {name}. This won't be a quick operation.", completion = "These cloaked beacons allow us to observe our enemies from afar and keep tabs on their movements.\n\nThey're not as effective as real scouts, but they'll do for now.\n\nNow, let's see how well organized they are.\n\nKnowing the Hal'hadar, they likely presume they are safe and out of reach from any threat.\n\nA mistake they will regret in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[96070] = { id = 96070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "12.1- Housing - Founders - Local Local Story 01 - Q01 - Escort - (POC)" }
quests[96080] = { id = 96080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Strike", description = "We have reports of new void strikes occurring around Eversong Forest and Zul'Aman. \n\nWe need you to head out immediately to investigate one of these strikes. I will mark your map with the latest location from our scouts.", sourceObjective = "Investigate a Void Strike.", progress = "What do you have to report?", completion = "I knew you were the right one for this mission. Your info has been critical on what we are now calling Void Assaults. Void forces, Twilight's Blade, Ethereals, and Naga have been striking us across the region.\n\nIt is unclear but early reports state the groups are not coordinating. \n\nWe need to outfit you and get you back out there!", sourceObjectiveStatus = "unverified-source-field" }
quests[96089] = { id = 96089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somethin's Not Right", description = "Whatever's wrong with her, whatever those creatures did, I need her healed!\n\nWill you help?", sourceObjective = "Help Scout Oma'ema figure out what's wrong with Medic La'una.", progress = "There's never a dull day on this island.", completion = "This is a recipe for an emetic. A vomit potion.\n\nThere's no better cure than to make her retch up whatever's ailing her.", sourceObjectiveStatus = "unverified-source-field" }
quests[96090] = { id = 96090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venemetic", description = "I have the other ingredients for the emetic here. The last ingredient I need is some venom to trigger a response.\n\nI overheard the trolls talk about a place just to the north called the Serpent's Tail. They say it's chock-full of venomous baddies, but we only need the poison from the Children of Ula'tek.\n\nThey say there are even rivers full of the caustic stuff, but don't go swimming in them. They're too concentrated and will eat right through the collection bottle before you can scream, \"I'm melting!\"", sourceObjective = "Collect 5 doses of Virulent Ula'tek Venom from the Children of Ula'tek at the Serpent's Tail.", progress = "Did you get all of it? I don't think your friend has much time.", completion = "Yep, this will do nicely. Ooh, but that toxic smell!\n\nReady to help me make the emetic?", sourceObjectiveStatus = "unverified-source-field" }
quests[96091] = { id = 96091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Balance Right", description = "I've set up three bottles with different ingredients. All you have to do is add just the right amount... just a dash of venom to each. Balance them out.\n\nYou can use Ofi's cauldron right over there. I'm sure she won't mind. Whatever's in there has likely been bubbling since before she was born.\n\nNo, I'm not going to do it for you. I've lived long enough to know not to touch that stuff!\n\nOnce you have the results, give the emetic to your medic friend and we'll see what happens.", sourceObjective = "Concoct the emetic at the cauldron and then administer it to Medic La'una.", progress = "Well, don't keep me waiting. Did you make the potion? Did you give it to her? Did it work?", completion = "That's unfortunate. I could hear it from here, the poor thing.\n\nOh well. Since that didn't work, I have another idea, though it'll be trickier. Up for some more adventure?", sourceObjectiveStatus = "unverified-source-field" }
quests[96092] = { id = 96092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Fool, Ruma", description = "Unfortunately, this has moved beyond my area of expertise.\n\nFortunately, I know someone who can help. Probably.\n\nUnfortunately, he left for some \"great adventure\" on Gnarldor Isle to the south. More likely, he's on a great bender.\n\nHere, take this elixir and give it to our former ship's doctor, Ruma. I always like to keep one handy. It'll sober him right up.\n\nThen it's on you to convince him to devise a cure. Good luck!", sourceObjective = "Find Scrollmaster Ruma on Gnarldor Isle and make sure he takes the Sobering Elixir.", completion = "Well, that was quite rude. Necessary perhaps, but rude nonetheless.\n\nHmm... Do I detect just a hint of aubergine?\n\n<Ruma smacks his lips.>\n\nThat elixir was most definitely Dezi's work. Tasty, but I wonder where she procured such a wonderful and rare fruit.", sourceObjectiveStatus = "unverified-source-field" }
quests[96093] = { id = 96093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Satchel, Not a Bag", description = "Well, you see, I was on quite the adventure with my friend, Tormunda, and a few others. Seeing the world, sipping exotic drinks, rest and relaxation. But then, disaster struck our camp.\n\nGnarldin!\n\nWe were separated and I did what you're supposed to do when you're lost: stay where you are. So, I've been resting here.\n\nBut I'm afraid in all the commotion, I left my satchel behind. It has all of my best things in it.\n\nSo you see, if you want my help, you'll have to go and get it for me.", sourceObjective = "Enter the Gnarldor Isle delve on any difficulty and retrieve Ruma's Satchel.", progress = "Did you find my satchel? All of my best drinks... er, scrolls are in it.", completion = "Oh good. I was worried it would be ransacked. Thank you, {name}.\n\nNow, you were saying something about a friend in need of a cure?", sourceObjectiveStatus = "unverified-source-field" }
quests[96094] = { id = 96094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Forum", description = "If we're to help this La'una of yours, we need to go to the source. You said they were scouting the western ledge of the Fangs when all of this happened?\n\nEveryone knows you don't go there. We should NOT go out there. But, that is precisely where we must go because that's where we'll find the cure.\n\nOr, meet our demise. Whichever comes first.\n\n<Ruma begins rummaging through his pack for a refreshment.>", sourceObjective = "Regroup with Scrollmaster Ruma at The Forum.", completion = "Told you I'd beat you here. That's the power of scrollomancy, my friend.\n\nGood thing your scout was already here. This is no place to be caught out on my own!", sourceObjectiveStatus = "unverified-source-field" }
quests[96095] = { id = 96095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sampling the Local Wildlife", description = "If I'm going to devise a cure, I need samples and plenty of them.\n\nLucky for us we have the two things we need: You and all of the infected wildlife roaming throughout this place.", sourceObjective = "Collect 10 Infectious Wildlife Samples and then give them to Scrollmaster Ruma to create the curative scroll.", progress = "This is the first step in finding a cure for whatever is going on out here.", completion = "Honestly, I don't know what all the fuss is about. Every experiment has its setbacks. I'll be fine.\n\nThe important thing is that we know more now than we did just a moment ago.", sourceObjectiveStatus = "unverified-source-field" }
quests[96096] = { id = 96096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout Team Seven", description = "When we first came out here our leader, Dusk Prowler Hano'mon, took de team too far in. He always was a... not very well-liked.\n\nI was scoutin' de rear and by de time I came across La'una, she was already affected by whatever dis is.\n\nIt's possible de rest of my scout team is still out there. If dey are, I need to know their fate, one way or de other.\n\nTheir names are A'pone, Kamaina, Ko'ruku, Uha'ne, and Hano'mon.", sourceObjective = "Determine the fates of the rest of Scout Team Seven.", progress = "Dis whole expedition was a mistake from de beginning. Hano'mon didn't bother to research before bringin' us out here.", completion = "<Oma'ema reaches out her hand to take the necklaces.>\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96097] = { id = 96097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Scouts Saw", description = "If my guess is correct, I think I know what we're missing.\n\nWould you be so kind as to ask these scouts about what they've seen while they were out there? I suspect they already know what, or who, is behind all of this.", sourceObjective = "Speak with the surviving members of Scout Team Seven.", progress = "Let's talk after you get both of their reports.", completion = "I agree with their scoutin' reports. Now it's time to act.", sourceObjectiveStatus = "unverified-source-field" }
quests[96098] = { id = 96098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Reagents", description = "I saw de Children of Ula'tek as well, {name}. Dey both are conjurin' in their separate towers out there.\n\nNow it's time to put an end to de threat. We can't have dem comin' out of de Vaults of Atal'Utek and spreadin' dis infection all over Zul'Aman... or farther.\n\nAnd don't forget about de reagents de doctor needs!", sourceObjective = "Collect Tetla'ketl's Conjuring Crest and Tsssaani's Scales of Summoning and then bring them back to Scrollmaster Ruma so that he can create the curative scroll. For real this time.", progress = "I'll be happy when we can get out of here with the cure.", completion = "Oh good. You know, we should sit and share one of my special concoctions after this is all done.", sourceObjectiveStatus = "unverified-source-field" }
quests[96099] = { id = 96099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "La'una's Fate", description = "The prescription is ready. Now all we have to do, all YOU have to do, is give it to the patient.\n\nDon't worry, it'll work. I'm sure of it. Well, I'm mostly sure. Let's say, sixty-seven percent certain. Those are pretty good odds considering the alternative.", sourceObjective = "Use Ruma's Infestation Eradicator on Medic La'una at Tokka's Landing.", progress = "I hope dis works.", completion = "You and de doctor are de best!\n\nIf you ever need anythin', you can count on Scout Team Seven, err... Four.", sourceObjectiveStatus = "unverified-source-field" }
quests[96110] = { id = 96110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom Fishing: Proof is in the Ooze", description = "If ye mean to be part of my crew, ye best be ready to handle the venom curse.\n\nKnow how to fish? Every creature with gills on this isle is ready to sink its teeth into you.\n\nProve ye can fish up even the smallest of the venom-cursed fish and I'll show ye how to take on deadlier and nastier fishin'.", sourceObjective = "Catch 5 Venom-Cursed Killifish in a venomous river.", progress = "These killifish are what the fresh Children of Ula'tek sup on once they crawl out o' yer corpse. If ye can't wrangle them, ye have no hope for the Great White Serpent.", completion = "That's a fine first haul. I'll tell ye a few more secrets to catchin' these, if ye can stomach it.", sourceObjectiveStatus = "unverified-source-field" }
quests[96111] = { id = 96111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom Fishing: Shell of Yourself", description = "You've learned some o' my secrets to fishin' in these cursed waters, but everything ye learn from here on serves a greater purpose than survival.\n\nRevenge.\n\nThe Great White Serpent that sank my ship is still alive. If we intend to kill it, we need the power o' my crew, now lost to the venom-curse.\n\nMaster Grenadier Birdie has one good shot: her first shot. Build yerself a decoy and you'll have a chance to kill her.\n\nTake her explosives. We'll need 'em to blow that snake to smithereens.", sourceObjective = "Collect 8 Wood Debris and craft a decoy of yourself to slay Master Grenadier Birdie.", progress = "Birdie could make an explosive out of anything. I wouldn't want to approach her now that her mind is full of venom.", completion = "It's just as I suspected. Birdie was holding back all those years, and now the venom has freed her from her moral compunctions.\n\nWe'll use her twisted devices for a good cause: destroying that cursed serpent!", sourceObjectiveStatus = "unverified-source-field" }
quests[96112] = { id = 96112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom Fishing: Maddening Concoction", description = "We need somethin' to protect that shell-less back o' yers when we face the Great White Serpent.\n\nLeathertongue made dishes that made us immune to nigh anything, this being on account o' them nearly killin' us every mealtime!\n\nHis pots and pans could withstand any nightmare. We need that strength.\n\nThe key to defeating the cook is to challenge his skill. Make a dish of the foulest ingredients and he'll be there to face ye.", sourceObjective = "Collect ingredients and slay Cook Leathertongue in Atal'Utek.", progress = "I've seen Leathertongue's cookpot lyin' empty for a full moon now. Whatever he's currently using to practice his venom-addled cookin' is sure to protect ye from the serpent.", completion = "I feared one day that Leathertongue would find a way to kill the crew with his dishes. That you've put that poor venom-cursed fool to rest puts me at ease.\n\nHis spare pot has seen a lot of use. It'll serve ye well.", sourceObjectiveStatus = "unverified-source-field" }
quests[96113] = { id = 96113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom Fishing: Maximum Potency", description = "We're almost ready to face the Great White Serpent. We only need one more thing.\n\nI want ye to take my quartermaster's boat.\n\nInktail has plans on plans. Before the venom, she was cool and reserved even in the wildest storms. With the venom curse, she's become even more elusive.\n\nI've only seen her lose her deadly composure once. She has a mighty love of rare fish.\n\nIt's a gamble, but go into the temple and find a fish overwhelmed with venom. It may be enough to draw her out of hidin'.", sourceObjective = "Collect a Black-Venom Grouper and slay Quartermaster Inktail in Atal'Utek.", progress = "More than any o' the others, Inktail is the one tortollan I would never face myself. Her paranoia has fueled her detailed preparations for longer than I've been alive.", completion = "You've done it. We have everything we need to face the Great White Serpent.\n\nThat snake's days are numbered.", sourceObjectiveStatus = "unverified-source-field" }
quests[96114] = { id = 96114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Pouch of Crystals", objectives = "Thanks for helping get Undermine back on track. Here's somethin' for your trouble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
