quests[96223] = { id = 96223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magisters' Call", description = "<A floating missive hangs before you, written in a flowing magical script. At first, it appears to be nonsense.\n\nAs you approach the parchment, the words shift and change, and a message forms.>\n\nThe Magisters request your presence at Thalassian University. Please proceed to the upper levels overlooking the harbor.\n\nThis concerns a private matter of minor urgency.", sourceObjective = "Travel to Thalassian University.", completion = "Ah, {name}. I see you received my message. Your timely response is most appreciated.\n\nWe have much to discuss and we are short on time, unfortunately.", sourceObjectiveStatus = "unverified-source-field" }
quests[96224] = { id = 96224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magisters' Conundrum", description = "Magisters' Terrace is home to many mysterious artifacts.\n\nAmong them is a relic once central to our pursuit of magical knowledge. A few years ago, the relic fell into a state of dormancy.\n\nAfter the Dawnwell reignited, this artifact began to stir. Upon returning it to the Lycaneum for study, the relic unleashed chaos upon the library.\n\nI believe your unique expertise may be helpful in quelling this chaos.", sourceObjective = "Join Magister Umbric and Grand Magister Rommath in Magisters' Terrace.", progress = "There is much to discuss.", completion = "<Rommath eyes you up and down for a moment.>\n\nSo, you're the outside help Magister Umbric summoned, are you? So be it.\n\nYou may very well be the first member of the Alliance to look upon the Sunstrider Omnium... even if it's seen better days.\n\nYears of dormancy and silence before suddenly awakening in a fit of arcane chaos.\n\nThere is much to do and many questions to answer.", sourceObjectiveStatus = "unverified-source-field" }
quests[96225] = { id = 96225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magisters' Conundrum", description = "For the last few decades, a dormant artifact laid beneath the halls of Magisters' Terrace.\n\nOnce serving as a beacon of knowledge to the Magisters, the artifact abruptly fell silent some decades ago.\n\nAfter the Dawnwell's rebirth, the artifact reawakened. When we returned it to the Lycaneum for study, it unleashed chaos upon the library.\n\nYour assistance, and discretion, would be most appreciated.", sourceObjective = "Join Magister Umbric and Grand Magister Rommath in Magisters' Terrace.", completion = "Ah, {name}. It seems the Grand Magister has become predictable with his choice of help. Very good.\n\nBefore you stands the Sunstrider Omnium. A once-silent, lifeless artifact for the last two decades... before its abrupt awakening not long ago.\n\nThe chaos it has unleashed poses a threat to all of Magisters' Terrace and perhaps beyond.\n\nWith your help, perhaps we can contain it.", sourceObjectiveStatus = "unverified-source-field" }
quests[96226] = { id = 96226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omnium Anomalies", description = "Shortly after the Omnium awoke, it began manifesting arcane anomalies around the Lycaneum.\n\nWe believe these anomalies to be malfunctioning security protocols--the hostile projections they conjure can be quite lethal.\n\nIf we do not dispatch them quickly, they will continue to manifest.\n\nAs you deal with them, keep an eye out for anything peculiar that can help us understand the Omnium's current state.", sourceObjective = "Confront the Arcane Anomalies around the Lycaneum.", progress = "These arcane anomalies are appearing all over the Terrace but thankfully, we've contained most of them.\n\nDo be careful, {name}. The ones here in the Lycaneum appear to be the most volatile.", completion = "The anomalies projected an image of Dar'Khan? Are you sure?\n\nWe knew that traitor came to the Magisters' Terrace to slaughter the convocation before disarming the Sunwell.\n\nThere was never any indication he damaged the Omnium. Not a mark, or scar on it.\n\nPerhaps Dar'Khan's damage was caused before Anasterian fell, resulting in the Omnium's abrupt silence...", sourceObjectiveStatus = "unverified-source-field" }
quests[96227] = { id = 96227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycaneum Chaos", description = "When the Omnium began to stir in its vault, we thought to move it here for observation. Evidently, this was a bad idea.\n\nThe arcane magics seeping out are causing chaos.\n\nFolios casting all sorts of incomplete spells, arcane sparks running amok--even the candle flames have sprung to life!\n\nBut we cannot simply destroy them, as the magics here are too volatile. I have procured a ward-lance from the arsenal of the spellbreakers. It will dispel the volatile magic.\n\nHere, take it. And do be careful.", sourceObjective = "Quell the arcane-induced chaos in the Lycaneum.", progress = "If one more folio explodes in my face, I may just torch every flying tome in this place.", completion = "<Rommath exhales a sigh of relief.>\n\nThe chaos may seem silly and the incantations harmless, but be reassured that if we hadn't contained it to the library, the entire building would be an academic uproar.\n\nFor the sake of all the Magisters here, I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96228] = { id = 96228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowed Spire", description = "Time and time again, Dar'Khan continues to haunt us in some form.\n\nTo think the Omnium also fell prey to his madness...\n\nIf he really severed the Void Magicule from the Omnium, then I have no doubt he would have hidden it well.\n\nI have a suspicion I know where to start looking.\n\nMeet me at Dawnstar Spire in Eversong Woods.", sourceObjective = "Meet up with Umbric at Dawnstar Spire.", progress = "To think that amidst the slaughter and bloodshed he unleashed that day, Dar'Khan took to desecrating an artifact even he sought to study...", completion = "With the anchors connected and stabilized, I can safely attune to the faint pulse we feel around us.\n\nWith enough luck, the void will reveal exactly where this pulse originates from.\n\nAnd knowing Dar'Khan, there is no doubt he left some sort of secondary ward or protective measure in place.\n\nReady yourself, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96229] = { id = 96229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void Reveals", description = "After reclaiming Silvermoon, the Magisters torched Dar'Khan's personal study and dwellings within the city walls.\n\nI had thought I had found everything I needed the first time I searched this place, but now...\n\nIt seems that Dar'Khan left some secrets.\n\nThis portal will take us to them. I do not know what we will find on the other side. Be on your guard.", sourceObjective = "Search Dawnstar Spire with Umbric.", progress = "I had thought every possible secret had been scoured from this cursed place. Leave it to Dar'Khan to conceal one last grim discovery for us...", completion = "<Umbric examines the Void Magicule in his palm, his lip curled slightly.>\n\nThere was a time when I would've rejoiced finding this relic... a time where I longed to peer into the secrets locked away within.\n\nBut knowing Dar'Khan recovered it while slaughtering the convocation of Silvermoon?\n\nA grim discovery, as are most things when it comes to that monster.", sourceObjectiveStatus = "unverified-source-field" }
quests[96230] = { id = 96230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unraveling the Wards", description = "The Magicules, the orbs you see on the relic, were never meant to be severed from the Omnium. By tearing one out, Dar'Khan likely sent the artifact into a frenzied state before it shut down. \n\nEven if the Void Magicule is restored, the Omnium will need recalibrating. We will need Belo'vir's key-cipher, now my key-cipher, to do this.\n\nI will meet you at my study and we can recover it.", sourceObjective = "Meet Grand Magister Rommath at his study on the Isle of Quel'Danas.", progress = "Leave it to Belo'vir Salonar to flaunt his mastery over the arcane one last time...", completion = "Belo'vir Salonar's mastery over the mirror image spell was known by many. His arcane thesis on 'Mirror Triplication' led to his first contribution into the Omnium's Arcane Magicule. \n\nIt was also his favorite spell to prank his apprentices with. I can't help but wonder if he knew how unamused I'd be at this attempt at one last joke.\n\nRegardless, excellent work. One last ward to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[96231] = { id = 96231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Magister's Key-Cipher", description = "After Belo'vir's death, I contemplated opening this vault. I talked myself out of it.\n\nA key for a shattered lock serves no purpose.\n\nAnd yet, even as Kael'thas tried to open it with his key, I couldn't help but wonder...\n\nIt doesn't matter, {name}. I am nearly done with the master ward on the upper floor. Meet me there.\n\nNo doubt, Belo'vir took extra steps to safeguard his vault.", sourceObjective = "Assist Grand Magister Rommath in unraveling Belo'vir's final safeguard.", progress = "After all this...", completion = "When I was an apprentice, Belo'vir gave a lecture on the Omnium's key-ciphers.\n\nTo protect the keys, each cipher took on the form known only to its owner.\n\nKael'thas had his key, now lost, and Belo'vir had his... sealed away in his vault.\n\nI wonder what shape Kael'thas used for his.\n\n<Rommath trails off as he stares at the key in his palm, its shifting image making it impossible to decipher.>", sourceObjectiveStatus = "unverified-source-field" }
quests[96232] = { id = 96232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Omnium", description = "Well, now that we've recovered the piece Dar'Khan stole, we are one step closer to restoring the Omnium.\n\nHopefully your endeavor with Rommath was a little less troublesome?\n\nWhen you're ready, return to the Magisters' Terrace. I will clean up anything left behind here and join you shortly.", sourceObjective = "Return to the Sunstrider Omnium in the Magisters' Terrace.", progress = "Without the missing lattice and the key-cipher, the Omnium will continue to spiral out of control.", completion = "I suppose we should be thankful that Dar'Khan decided to bury so many of his secrets within that accursed place.\n\nI shudder to think what might have happened had he hid the Void Magicule within Deathholme and allowed it to fall into the hands of the Scourge or the Twilight's Blade.\n\nOnly one task yet remains, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96233] = { id = 96233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Omnium Reawakens", description = "For years, as Silvermoon and its people changed, this relic sat in a vault beneath the Terrace, unresponsive and dormant.\n\nWe may never truly understand why the relic fell silent when it did or why it refused the prince's call, but perhaps in time, we might.\n\nLet us hope the missing Magicule and the key-cipher will be enough to restore it.\n\nAre you ready, {name}?", sourceObjective = "Speak with Grand Magister Rommath to begin.", completion = "Most Magisters--myself included-- had simply given up hope we would ever see it restored.\n\nWas it the Void's assault on the Sunwell that stirred it? Or the Dawnwell? Perhaps we'll never know.\n\nWhat I do know is that we stand in its presence thanks to you, {name}.\n\nNormally I'd bid you farewell with a handsome reward, but perhaps there is more you can help us with.\n\nWith, of course, an even greater reward...", sourceObjectiveStatus = "unverified-source-field" }
quests[96238] = { id = 96238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Omnium", description = "With Belo'vir's key-cipher recovered and Umbric in possession of the Void Magicule, we should return to the Lycaneum.\n\nHopefully we have all that we need to recalibrate the Sunstrider Omnium.\n\nI will meet you back in the Magisters' Terrace when I am done here.", sourceObjective = "Return to the Sunstrider Omnium in the Magisters' Terrace.", progress = "Without the missing lattice and the key-cipher, we have no means of stopping the Omnium's malfunctions.", completion = "When I took up the mantle of Grand Magister, there was much to account for in such a chaotic time.\n\nThe key-cipher I inherited seemed unimportant at the time, especially when the prince's own key was ineffective.\n\nI pray that whatever interfered with the Sunstrider key-cipher doesn't interfere today.\n\nWe have but one task remaining.", sourceObjectiveStatus = "unverified-source-field" }
quests[96242] = { id = 96242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Easy Path to Trickery", description = "You can always speak to me to enter a game of Decor Duel, but did you know there's an easier way?\n\nIf there's a group you want to find, we have \"magic\" to help!", sourceObjective = "<Open the Group Finder, select Player vs. Player, and then select Decor Duel.>", progress = "You're on the easy path to Trickery? Good luck!\n\n<use Group Finder to play a PvP Decor Duel match.>\n\n<If you abandon her quest, or complete it, you may re-enter Decor Duel through Amolene again>", completion = "Excellent! Great work, {name}. Don't forget to check in often! You'll want to make sure you unlock the full potential of all the Kits available in order to maximize your enjoyment--and points-earning potential, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[96245] = { id = 96245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Seen it All Before", description = "<A fine parchment materializes in a shower of bronze dust. It is an invitation from Soridormi to visit her at the Wayfarer's Rest in Silvermoon City.>", sourceObjective = "Visit Soridormi at the Wayfarer's Rest in Silvermoon City.", progress = "What brings you here?", completion = "Ah, good to see you again. Or perhaps this is the first time we've met? Sorry, timelines get rather tangled in times of crisis. Let me know if you'd like me to sort yours out.", sourceObjectiveStatus = "unverified-source-field" }
quests[96267] = { id = 96267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancestral Gems", description = "When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic!\n\nAmong these items were some gems of great power.\n\nSearch de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.", sourceObjective = "Recover 30 Ritual Gems from the deepest interiors of the Vaults of Atal'Utek.", progress = "Have you recovered de gems?", completion = "De Children of Ula'tek won't be meddlin' with these gems anymore. I won't forget dis deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[96268] = { id = 96268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsh Mana Spores" }
quests[96271] = { id = 96271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Existence", description = "When de poison spread through dis temple, many of our ancestors fell trying to defend dis place.\n\nNow Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.", sourceObjective = "Slay Jarza the Cursed, Venomous Revenant Zal'kir, Coil-Cursed Vok'tara, and other servants of Nek'zali.", completion = "Ya brought merciful peace to the ancestors with dis deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[96272] = { id = 96272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mashing Mushroom Mana Machines" }
quests[96273] = { id = 96273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Balance Paid in Blood", description = "De Children of Ula'tek have upset de balance of de spirit world. Many spirits are angry and demand justice before dey can move on.\n\nDe snakes' blood will restore de balance!\n\nSlay de Children of Ula'tek and all dat aid dem here in de temple.", sourceObjective = "Slay enemies within the Vaults of Atal'Utek.", progress = "Have you done dis work?", completion = "De spirits see what ya done, and rest now in de balance you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[96275] = { id = 96275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wading In", description = "Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others.\n\nPlace spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. \n\nDe venom lakes are deadly, so go prepared!", sourceObjective = "Place 8 Spirit Guardians at locations in the venom.", completion = "De spirits whisper to me. Dey are thankful for de safety ya give them.", sourceObjectiveStatus = "unverified-source-field" }
